import{_ as a,o as e,c as i,ae as n}from"./chunks/framework.Bwt6MOeu.js";const h=JSON.parse('{"title":"Guardian Consent and Minor Access Model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/guardian-consent-and-minor-access-model.md","filePath":"guide/guardian-consent-and-minor-access-model.md"}'),r={name:"guide/guardian-consent-and-minor-access-model.md"};function o(d,t,l,s,c,p){return e(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="guardian-consent-and-minor-access-model" tabindex="-1">Guardian Consent and Minor Access Model <a class="header-anchor" href="#guardian-consent-and-minor-access-model" aria-label="Permalink to &quot;Guardian Consent and Minor Access Model&quot;">​</a></h1><p>SocioProphet uses a conservative minor-access model.</p><p>Legal requirements vary by jurisdiction, but the product default is simple: minors receive more protection, not less.</p><h2 id="participation-classes" tabindex="-1">Participation classes <a class="header-anchor" href="#participation-classes" aria-label="Permalink to &quot;Participation classes&quot;">​</a></h2><h3 id="adult-independent-participant" tabindex="-1">Adult / independent participant <a class="header-anchor" href="#adult-independent-participant" aria-label="Permalink to &quot;Adult / independent participant&quot;">​</a></h3><p>Full self-managed account and connection flow, subject to role and policy.</p><h3 id="guardian-linked-minor-participant" tabindex="-1">Guardian-linked minor participant <a class="header-anchor" href="#guardian-linked-minor-participant" aria-label="Permalink to &quot;Guardian-linked minor participant&quot;">​</a></h3><p>Minor participation is tied to a guardian or authorized institutional sponsor.</p><h3 id="institution-governed-minor-participant" tabindex="-1">Institution-governed minor participant <a class="header-anchor" href="#institution-governed-minor-participant" aria-label="Permalink to &quot;Institution-governed minor participant&quot;">​</a></h3><p>Minor participation may be mediated through an approved program, school, or supervised learning setting, but still remains more restricted than ordinary adult use.</p><h2 id="capability-classes" tabindex="-1">Capability classes <a class="header-anchor" href="#capability-classes" aria-label="Permalink to &quot;Capability classes&quot;">​</a></h2><p>SocioProphet separates capabilities into classes:</p><ul><li>learning and reading</li><li>collaboration and messaging</li><li>provider connections</li><li>automation and browsing</li><li>local runtime / execution</li><li>elevated or sensitive domains</li></ul><h2 id="default-access-model" tabindex="-1">Default access model <a class="header-anchor" href="#default-access-model" aria-label="Permalink to &quot;Default access model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability class</th><th>Adult</th><th>Guardian-linked minor</th><th>Institution-governed minor</th></tr></thead><tbody><tr><td>Learning / reading</td><td>Allowed</td><td>Allowed</td><td>Allowed</td></tr><tr><td>Collaboration / messaging</td><td>Allowed</td><td>Conditional</td><td>Conditional</td></tr><tr><td>Provider self-connection</td><td>Allowed</td><td>Restricted</td><td>Restricted</td></tr><tr><td>Browser automation</td><td>Allowed</td><td>Restricted</td><td>Restricted</td></tr><tr><td>Local runtime / execution</td><td>Allowed</td><td>Restricted</td><td>Restricted</td></tr><tr><td>Sensitive / elevated domains</td><td>Conditional</td><td>Restricted</td><td>Conditional</td></tr></tbody></table><h2 id="product-rule" tabindex="-1">Product rule <a class="header-anchor" href="#product-rule" aria-label="Permalink to &quot;Product rule&quot;">​</a></h2><p>Minors do not self-assemble high-risk provider or runtime capability by default.</p><p>Guardian and institutional controls are not an afterthought. They are part of the default operating model.</p><h2 id="required-platform-behaviors" tabindex="-1">Required platform behaviors <a class="header-anchor" href="#required-platform-behaviors" aria-label="Permalink to &quot;Required platform behaviors&quot;">​</a></h2><p>The platform must support:</p><ul><li>guardian-linked visibility</li><li>explicit consent checkpoints</li><li>capability restrictions by participant class</li><li>incident reporting and escalation</li><li>recoverable auth and connection flows that do not bypass supervision</li></ul>',21)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
